mapper.select:
SELECT id, knowledge_base_id as knowledgeBaseId, skill_id as skillId,
       difficulty, type, category, question, topic_summary as topicSummary,
       reference_answer as referenceAnswer, key_points as keyPoints,
       scoring_rubric as scoringRubric, follow_ups as followUps,
       source_context as sourceContext, status,
       created_at::timestamp as createdAt, updated_at::timestamp as updatedAt
FROM knowledge_base_questions
WHERE knowledge_base_id = #{kbId}

      AND status = #{status}


      AND category = #{category}


      AND difficulty = #{difficulty}


      AND (question LIKE CONCAT('%', #{keyword}, '%') OR topic_summary LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY id DESC
